-- 184: Original BrillaPrep WASSCE BrillaPrep transitional Woodwork beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_184_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_184_guard;
INSERT INTO _migration_184_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_021' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_5' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a riving knife on a circular saw?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Keep the kerf open and reduce kickback from closing timber","B. Cover the blade teeth below the table only","C. Increase blade diameter during cutting","D. Hold the operator’s hand near the cut"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The riving knife follows the blade and limits the workpiece pinching the rear teeth, a common cause of violent kickback. Therefore the correct answer is A: Keep the kerf open and reduce kickback from closing timber.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_021' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_184_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_022' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_5' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a push stick be used when ripping narrow stock on a circular saw?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Replace the rip fence as the dimensional guide","B. Keep hands away from the blade while maintaining feed control","C. Press the timber sideways into the rear teeth","D. Allow loose offcuts to be removed while the blade turns"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A push stick maintains forward and downward control without placing fingers inside the hazardous zone near the blade. Therefore the correct answer is B: Keep hands away from the blade while maintaining feed control.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_022' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_184_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_023' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_5' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What must be done before changing a cutter on a woodworking machine?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Rely only on the stop button while power remains connected","B. Hold the cutter by hand and briefly start the motor","C. Isolate the machine from its energy source and verify it cannot start","D. Remove all guards while the spindle coasts"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Positive isolation prevents unexpected starting or stored-energy movement during contact with sharp tooling. Therefore the correct answer is C: Isolate the machine from its energy source and verify it cannot start.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_023' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_184_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_024' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_5' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are planer knives set to equal projection in the cutter block?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Make one knife take the entire cut","B. Increase vibration deliberately","C. Create a tapered board regardless of settings","D. Maintain balance and produce a consistent surface"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Unequal knives cause vibration, uneven cutting and high loads, while matched projection shares work and maintains the cutting circle. Therefore the correct answer is D: Maintain balance and produce a consistent surface.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_024' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_184_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_025' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_5' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the correct response to unusual vibration from a woodworking machine?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Stop, isolate and inspect before further use","B. Increase feed pressure until vibration disappears","C. Remove the guard while the machine runs","D. Ignore it if the timber still advances"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Unexpected vibration can indicate loose tooling, damage, imbalance or bearing failure and may precede dangerous component release. Therefore the correct answer is A: Stop, isolate and inspect before further use.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_025' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
